package com.kuswa.clashtimer.core

import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.jsonObject

/**
 * `data` ID → display name, in three layers (plan 1.1 §4):
 * 1. names the player typed on the "Unknown items" screen ([user]),
 * 2. `assets/names_overrides.json` (hand-maintained, e.g. TH19 items),
 * 3. `assets/names.json` (generated by `tools/gen_names.cjs` from the clash-of-clans-data package).
 * An ID in none of them gets a category name (`New building`, `New squad`, …) on the widget; the raw ID
 * only shows in the app's diagnostics.
 */
class NameMap(
    private val generated: Map<Int, String>,
    private val overrides: Map<Int, String> = emptyMap(),
    private val user: Map<Int, String> = emptyMap(),
) {

    /** Number of bundled names (generated + overrides). */
    val size: Int get() = (generated.keys + overrides.keys).size

    /** The same bundled names with the player's own names on top. */
    fun withUser(names: Map<Int, String>): NameMap = NameMap(generated, overrides, names.filterValues { it.isNotBlank() })

    fun nameOrNull(id: Int): String? = user[id] ?: overrides[id] ?: generated[id]

    fun has(id: Int): Boolean = nameOrNull(id) != null

    /** Named by the app itself (not only by the player): the "Unknown items" screen lists the others. */
    fun hasBundled(id: Int): Boolean = id in overrides || id in generated

    /** Real name, or the category name for IDs added in future game updates. */
    fun name(id: Int, kind: ItemKind): String = nameOrNull(id) ?: fallback(kind)

    /** Widget label: `Wizard Tower → 17`, `Super Wizard Tower (new)`, `Cake-A-Pult Damage → 8`. */
    fun label(job: Job): String =
        if (job.isNewBuilding) "${title(job)} (new)" else "${title(job)} → ${job.targetLevel}"

    /** The name part of [label]: `Wizard Tower`, `Cake-A-Pult Damage` (crafted defense + module). */
    fun title(job: Job): String = when (job.source) {
        JobSource.MODULE -> {
            val defense = (job.typeDataId?.let(::nameOrNull) ?: job.parentDataId?.let(::nameOrNull))
            val module = nameOrNull(job.dataId)
            when {
                defense != null && module != null -> "$defense $module"
                defense != null -> "$defense module"
                else -> module ?: fallback(ItemKind.MODULE)
            }
        }
        else -> name(job.dataId, job.source.itemKind)
    }

    /** True when the job's own item has a real name (its [title] is not a category fallback). */
    fun isKnown(job: Job): Boolean = has(job.dataId)

    companion object {
        /** Widget name for an ID the app doesn't know yet. Troops are "squads" since TH19. */
        fun fallback(kind: ItemKind): String = when (kind) {
            ItemKind.BUILDING, ItemKind.MODULE -> "New building"
            ItemKind.TRAP -> "New trap"
            ItemKind.HERO -> "New hero"
            ItemKind.GUARDIAN -> "New guardian"
            ItemKind.TROOP -> "New squad"
            ItemKind.SPELL -> "New spell"
            ItemKind.SIEGE_MACHINE -> "New siege machine"
            ItemKind.PET -> "New pet"
        }

        /** Parses `{"names": {"id": "Name"}}` (or a bare `{"id": "Name"}` object); other keys are skipped. */
        fun parse(text: String): Map<Int, String> {
            val root = Json.parseToJsonElement(text).jsonObject
            val obj = root["names"] as? JsonObject ?: root
            return obj.entries.mapNotNull { (k, v) ->
                val id = k.toIntOrNull() ?: return@mapNotNull null
                val name = (v as? JsonPrimitive)?.takeIf { it.isString }?.content ?: return@mapNotNull null
                id to name
            }.toMap()
        }

        fun fromJson(text: String, overridesText: String? = null): NameMap =
            NameMap(parse(text), overridesText?.let(::parse) ?: emptyMap())
    }
}
